// Tier 4: Venn Diagram Data — Interactive Sorting Exercise
// Students sort features into: Term A Only | Shared | Term B Only | Does Not Belong
export interface VennItem {
  id: string;
  conceptA: string;
  conceptB: string;
  category: string;
  domain: string;
  domainFull: string;
  onlyA: string[];      // features unique to Term A
  onlyB: string[];      // features unique to Term B
  shared: string[];     // features true of BOTH
  distractors: string[]; // plausible-sounding features that belong to NEITHER
  keyDistinction: string;
}

